    char buf[32];
    strcpy(buf, src);
    printf("%s", buf);
}

fixed_code:
void copy_name(char *src) {
    char buf[32];
    strncpy(buf, src, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = 0;
    printf("%s", buf);
}

